#!/usr/bin/env bash
# step107 — Batch 3: coupon engine + admin. Adds coupons table (seeds GALAXY10),
# lib/coupon.js, /admin/coupons (create/edit/enable/feature/delete), mount + nav.
# Checkout application + promo-bar wiring come next (step108). Idempotent; rollback.
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step107-$TS
mkdir -p "$BAK" "$BAK/views/admin"
cp "$APP/server.js" "$BAK/server.js"
cp "$APP/views/admin/_shell_top.ejs" "$BAK/views/admin/_shell_top.ejs"
restore(){ echo "!! rollback"; cp "$BAK/server.js" "$APP/server.js"; cp "$BAK/views/admin/_shell_top.ejs" "$APP/views/admin/_shell_top.ejs"; rm -f "$APP/lib/coupon.js" "$APP/routes/adminCoupons.js" "$APP/views/admin/coupons.ejs"; pm2 restart gsz --update-env >/dev/null 2>&1 || true; }
trap 'restore' ERR
cd "$APP"

echo "==> migrate: coupons table (+ seed GALAXY10)"
node <<'NODE'
require('dotenv').config();
const { Pool } = require('pg');
const p = new Pool({ host:process.env.DB_HOST, port:process.env.DB_PORT, database:process.env.DB_NAME, user:process.env.DB_USER, password:process.env.DB_PASS });
(async()=>{
  await p.query(`CREATE TABLE IF NOT EXISTS coupons(
    id serial PRIMARY KEY, code text NOT NULL, kind text NOT NULL DEFAULT 'percent',
    value numeric NOT NULL DEFAULT 0, min_order_pkr numeric NOT NULL DEFAULT 0,
    max_discount_pkr numeric, expires_at timestamptz, usage_limit integer,
    used_count integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true,
    featured boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now())`);
  await p.query("CREATE UNIQUE INDEX IF NOT EXISTS coupons_code_uidx ON coupons(upper(code))");
  await p.query("INSERT INTO coupons(code,kind,value,active,featured) VALUES('GALAXY10','percent',10,true,true) ON CONFLICT(upper(code)) DO NOTHING");
  const n=(await p.query('SELECT count(*)::int n FROM coupons')).rows[0].n;
  console.log('   coupons ready ('+n+' code(s))');
  await p.end();
})().catch(e=>{ console.error('MIGRATION FAIL: '+e.message); process.exit(1); });
NODE

echo "==> write lib/coupon.js + route + view"
base64 -d > "$APP/lib/coupon.js" <<'B64'

B64
base64 -d > "$APP/routes/adminCoupons.js" <<'B64'

B64
base64 -d > "$APP/views/admin/coupons.ejs" <<'B64'

B64

echo "==> mount + nav"
node <<'NODE'
const fs=require('fs'); const f='/opt/gsz/server.js'; let s=fs.readFileSync(f,'utf8');
if(s.indexOf('adminCoupons')<0){
  const a="const adminMessagesRouter = require('./routes/adminMessages')(pool);\napp.use('/admin', adminMessagesRouter);";
  if(s.indexOf(a)<0){ console.error('!! adminMessages mount anchor not found'); process.exit(2); }
  s=s.replace(a, a+"\nconst adminCouponsRouter = require('./routes/adminCoupons')(pool);\napp.use('/admin', adminCouponsRouter);");
  fs.writeFileSync(f,s); console.log('   server mounted');
} else console.log('   server already');
const nf='/opt/gsz/views/admin/_shell_top.ejs'; let ns=fs.readFileSync(nf,'utf8');
if(ns.indexOf("on('coupons')")<0){
  const a='</svg>Bot messages</a>';
  if(ns.indexOf(a)<0){ console.error('!! Bot messages nav anchor not found'); process.exit(3); }
  ns=ns.replace(a, a+"\n    <a href=\"/admin/coupons\" class=\"<%= on('coupons') %>\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 9V6a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v3a2 2 0 0 0 0 6v3a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2v-3a2 2 0 0 0 0-6z\"/><path d=\"M9 9v6\"/></svg>Discount codes</a>");
  fs.writeFileSync(nf,ns); console.log('   nav added');
} else console.log('   nav already');
NODE

echo "==> node --check + ejs compile + restart"
node --check "$APP/lib/coupon.js"; node --check "$APP/routes/adminCoupons.js"; node --check "$APP/server.js"
node -e "const ejs=require('ejs'),fs=require('fs');['views/admin/coupons.ejs','views/admin/_shell_top.ejs'].forEach(v=>{ejs.compile(fs.readFileSync('$APP/'+v,'utf8'),{filename:'$APP/'+v});});console.log('   views compile');"
pm2 restart gsz --update-env >/dev/null; sleep 3
grep -q '</html>' <<<"$(curl -s -m 15 http://127.0.0.1:3900/ || true)" || { echo "!! home broken"; false; }
C1=$(curl -s -o /dev/null -w '%{http_code}' -m 10 http://127.0.0.1:3900/admin/coupons || true)
[ "$C1" = "302" ] || { echo "!! /admin/coupons should redirect to admin login (got $C1)"; false; }
trap - ERR
echo "==> step107 OK — coupon engine + admin at /admin/coupons. Backup: $BAK"
